import { describe, it, expect } from "vitest";
import { z } from "zod";
import { createService, decodeCursor, encodeCursor } from "../service/createService";
import { isErr, isOk } from "../result";

// ---------------------------------------------------------------------------
// Minimal in-memory Supabase stub
// ---------------------------------------------------------------------------

interface Row {
  id: string;
  title: string;
  org_id: string;
  created_at: string;
  updated_at: string;
  deleted_at: string | null;
}

const rowSchema = z.object({
  id: z.string(),
  title: z.string(),
  org_id: z.string(),
  created_at: z.string(),
  updated_at: z.string(),
  deleted_at: z.string().nullable(),
});

const inputSchema = z.object({
  title: z.string().min(1),
  org_id: z.string(),
});

type QueryOp =
  | { kind: "select" }
  | { kind: "insert"; payload: Record<string, unknown> }
  | { kind: "update"; payload: Record<string, unknown> };

function makeStub(initial: Row[]): { supabase: unknown; rows: () => Row[] } {
  let rows = [...initial];
  function from(_table: string) {
    // Each call returns a fresh chain proxy. We record operations minimally.
    let op: QueryOp = { kind: "select" };
    const filters: Array<(r: Row) => boolean> = [];
    let limitVal: number | null = null;
    let single = false;
    let maybe = false;
    // eslint-disable-next-line @typescript-eslint/no-explicit-any
    const chain: any = {
      select: () => {
        op = { kind: "select" };
        return chain;
      },
      insert: (payload: Record<string, unknown>) => {
        op = { kind: "insert", payload };
        return chain;
      },
      update: (payload: Record<string, unknown>) => {
        op = { kind: "update", payload };
        return chain;
      },
      eq: (col: string, val: unknown) => {
        filters.push((r) => (r as unknown as Record<string, unknown>)[col] === val);
        return chain;
      },
      is: (col: string, val: unknown) => {
        filters.push((r) => (r as unknown as Record<string, unknown>)[col] === val);
        return chain;
      },
      or: () => chain,
      order: () => chain,
      limit: (n: number) => {
        limitVal = n;
        return chain;
      },
      abortSignal: () => chain,
      single: () => {
        single = true;
        return chain;
      },
      maybeSingle: () => {
        maybe = true;
        return chain;
      },
      then: (resolve: (r: { data: unknown; error: unknown }) => void) => {
        let matched = rows.filter((r) => filters.every((f) => f(r)));
        if (limitVal !== null) matched = matched.slice(0, limitVal);
        if (op.kind === "insert") {
          const p = op.payload;
          const id = (p["id"] as string) ?? `new-${rows.length + 1}`;
          const now = new Date().toISOString();
          const created: Row = {
            id,
            title: String(p["title"] ?? ""),
            org_id: String(p["org_id"] ?? ""),
            created_at: now,
            updated_at: now,
            deleted_at: null,
          };
          rows.push(created);
          return resolve({ data: created, error: null });
        }
        if (op.kind === "update") {
          const target = matched[0];
          if (!target) return resolve({ data: null, error: null });
          const updated = { ...target, ...op.payload };
          rows = rows.map((r) => (r.id === target.id ? (updated as Row) : r));
          return resolve({ data: updated, error: null });
        }
        // select
        if (single) return resolve({ data: matched[0] ?? null, error: null });
        if (maybe) return resolve({ data: matched[0] ?? null, error: null });
        return resolve({ data: matched, error: null });
      },
    };
    return chain;
  }
  return { supabase: { from } as unknown, rows: () => rows };
}

// ---------------------------------------------------------------------------
// Tests
// ---------------------------------------------------------------------------

describe("encodeCursor / decodeCursor", () => {
  it("round-trips a (sort, id) tuple", () => {
    const c = encodeCursor("2026-04-21T00:00:00Z", "abc-1");
    const d = decodeCursor(c);
    expect(d).toEqual(["2026-04-21T00:00:00Z", "abc-1"]);
  });

  it("returns null for malformed cursors", () => {
    expect(decodeCursor("not-valid")).toBeNull();
  });
});

describe("createService — happy path", () => {
  it("list returns a validated page with nextCursor", async () => {
    const { supabase } = makeStub([
      {
        id: "1",
        title: "A",
        org_id: "org-1",
        created_at: "2026-04-21T00:00:00Z",
        updated_at: "2026-04-21T00:00:00Z",
        deleted_at: null,
      },
    ]);
    // eslint-disable-next-line @typescript-eslint/no-explicit-any
    const svc = createService<Row, { title: string; org_id: string }>(supabase as any, {
      table: "risks",
      rowSchema,
      inputSchema,
    });
    const r = await svc.list({ limit: 10 });
    expect(isOk(r)).toBe(true);
    if (r.ok) {
      expect(r.value.items).toHaveLength(1);
      expect(r.value.nextCursor).toBeNull();
    }
  });

  it("get returns not_found when the row is missing", async () => {
    const { supabase } = makeStub([]);
    // eslint-disable-next-line @typescript-eslint/no-explicit-any
    const svc = createService<Row, { title: string; org_id: string }>(supabase as any, {
      table: "risks",
      rowSchema,
      inputSchema,
    });
    const r = await svc.get("missing");
    expect(isErr(r)).toBe(true);
    if (!r.ok) expect(r.error.code).toBe("not_found");
  });

  it("create validates input and rejects bad payloads before any IO", async () => {
    const { supabase } = makeStub([]);
    // eslint-disable-next-line @typescript-eslint/no-explicit-any
    const svc = createService<Row, { title: string; org_id: string }>(supabase as any, {
      table: "risks",
      rowSchema,
      inputSchema,
    });
    const r = await svc.create({ title: "", org_id: "org-1" } as never);
    expect(isErr(r)).toBe(true);
    if (!r.ok) expect(r.error.code).toBe("validation");
  });

  it("remove performs a soft delete", async () => {
    const { supabase, rows } = makeStub([
      {
        id: "1",
        title: "A",
        org_id: "org-1",
        created_at: "2026-04-21T00:00:00Z",
        updated_at: "2026-04-21T00:00:00Z",
        deleted_at: null,
      },
    ]);
    // eslint-disable-next-line @typescript-eslint/no-explicit-any
    const svc = createService<Row, { title: string; org_id: string }>(supabase as any, {
      table: "risks",
      rowSchema,
      inputSchema,
    });
    const r = await svc.remove("1");
    expect(isOk(r)).toBe(true);
    expect(rows()[0]?.deleted_at).not.toBeNull();
  });

  it("bulk aggregates per-item success and failure", async () => {
    const { supabase } = makeStub([
      {
        id: "1",
        title: "A",
        org_id: "org-1",
        created_at: "t",
        updated_at: "t",
        deleted_at: null,
      },
      {
        id: "2",
        title: "B",
        org_id: "org-1",
        created_at: "t",
        updated_at: "t",
        deleted_at: null,
      },
    ]);
    // eslint-disable-next-line @typescript-eslint/no-explicit-any
    const svc = createService<Row, { title: string; org_id: string }>(supabase as any, {
      table: "risks",
      rowSchema,
      inputSchema,
    });
    const r = await svc.bulk(["1", "2"], { title: "renamed" });
    expect(isOk(r)).toBe(true);
    if (r.ok) {
      expect(r.value.succeeded).toHaveLength(2);
      expect(r.value.failed).toHaveLength(0);
    }
  });
});

describe("createService — security", () => {
  it("does not allow components to bypass deleted_at filter (list default)", async () => {
    const { supabase } = makeStub([
      {
        id: "1",
        title: "A",
        org_id: "org-1",
        created_at: "t",
        updated_at: "t",
        deleted_at: "2026-04-21T00:00:00Z",
      },
    ]);
    // eslint-disable-next-line @typescript-eslint/no-explicit-any
    const svc = createService<Row, { title: string; org_id: string }>(supabase as any, {
      table: "risks",
      rowSchema,
      inputSchema,
    });
    const r = await svc.list();
    expect(isOk(r)).toBe(true);
    if (r.ok) expect(r.value.items).toHaveLength(0);
  });
});

// Licensed to CERTIFYI-AI under the Apache License, Version 2.0.
// Generic typed service factory — generates list/get/create/update/delete/bulk
// for any Supabase table. Enforces org_id scoping on every query.
import type { ZodSchema } from 'zod'
import { supabase } from './supabase'
import { ok, err, type Result } from '../types/errors'

/** Thrown when input validation fails (used by simplified API overloads). */
export class ServiceError extends Error {
  constructor(
    public readonly code: string,
    message: string,
  ) {
    super(message)
    this.name = 'ServiceError'
  }
}

export interface ServiceConfig<_TSchema extends ZodSchema, T> {
  table: string
  schema: _TSchema
  /** Optional input-only schema; stricter than the full row schema. */
  inputSchema?: ZodSchema
  orgField?: string     // column name for org/tenant scoping (default: 'org_id')
  softDelete?: boolean  // use deleted_at instead of hard DELETE
  defaultOrder?: { column: string; ascending: boolean }
}

export interface ListOptions {
  orgId: string
  limit?: number
  offset?: number
  filters?: Record<string, unknown>
  search?: string
  order?: { column: string; ascending: boolean }
}

export function createService<TSchema extends ZodSchema, T extends Record<string, unknown>>(
  config: ServiceConfig<TSchema, T>
) {
  const { table, schema, orgField = 'org_id', softDelete = false } = config

  async function list(opts: ListOptions): Promise<Result<T[]>> {
    let q = supabase
      .from(table)
      .select('*', { count: 'exact' })
      .eq(orgField, opts.orgId)

    if (softDelete) q = q.is('deleted_at', null)

    if (opts.filters) {
      Object.entries(opts.filters).forEach(([k, v]) => {
        if (v !== undefined && v !== null && v !== '') q = q.eq(k, v)
      })
    }

    const order = opts.order ?? config.defaultOrder ?? { column: 'created_at', ascending: false }
    q = q.order(order.column, { ascending: order.ascending })

    if (opts.limit) q = q.limit(opts.limit)
    if (opts.offset !== undefined && opts.limit !== undefined) {
      q = q.range(opts.offset, opts.offset + opts.limit - 1)
    }

    const { data, error } = await q
    if (error) return err('LIST_FAILED', error.message)
    return ok((data ?? []) as T[])
  }

  async function get(id: string, orgId: string): Promise<Result<T>> {
    const { data, error } = await supabase
      .from(table)
      .select('*')
      .eq('id', id)
      .eq(orgField, orgId)
      .single()
    if (error) return err('GET_FAILED', error.message)
    if (!data) return err('NOT_FOUND', `${table} ${id} not found`)
    return ok(data as T)
  }

  async function create(input: Partial<T>): Promise<Result<T>> {
    const parsed = schema.safeParse(input)
    if (!parsed.success) {
      return err('VALIDATION_ERROR', 'Validation failed', parsed.error.message)
    }
    const { data, error } = await supabase
      .from(table)
      .insert(parsed.data as Record<string, unknown>)
      .select()
      .single()
    if (error) return err('CREATE_FAILED', error.message)
    return ok(data as T)
  }

  async function update(id: string, orgId: string, input: Partial<T>): Promise<Result<T>> {
    // eslint-disable-next-line @typescript-eslint/no-explicit-any
    const partial = (schema as any).partial().safeParse(input)
    if (!partial.success) {
      return err('VALIDATION_ERROR', 'Validation failed', partial.error.message)
    }
    const { data, error } = await supabase
      .from(table)
      .update({ ...(partial.data as Record<string, unknown>), updated_at: new Date().toISOString() })
      .eq('id', id)
      .eq(orgField, orgId)
      .select()
      .single()
    if (error) return err('UPDATE_FAILED', error.message)
    return ok(data as T)
  }

  async function remove(id: string, orgId: string): Promise<Result<void>> {
    if (softDelete) {
      const { error } = await supabase
        .from(table)
        .update({ deleted_at: new Date().toISOString() })
        .eq('id', id)
        .eq(orgField, orgId)
      if (error) return err('DELETE_FAILED', error.message)
      return ok(undefined)
    }
    const { error } = await supabase
      .from(table)
      .delete()
      .eq('id', id)
      .eq(orgField, orgId)
    if (error) return err('DELETE_FAILED', error.message)
    return ok(undefined)
  }

  async function bulk(operation: 'create' | 'update' | 'delete', items: Partial<T>[], orgId: string): Promise<Result<T[]>> {
    if (operation === 'create') {
      const { data, error } = await supabase.from(table).insert(items as Record<string, unknown>[]).select()
      if (error) return err('BULK_FAILED', error.message)
      return ok((data ?? []) as T[])
    }
    // Simplified bulk delete
    if (operation === 'delete') {
      const ids = items.map(i => (i as Record<string, unknown>)['id'] as string).filter(Boolean)
      const { error } = await supabase.from(table).delete().in('id', ids).eq(orgField, orgId)
      if (error) return err('BULK_DELETE_FAILED', error.message)
      return ok([])
    }
    return ok([])
  }

  return { list, get, create, update, remove, bulk }
}

