        searchPlaceholder="Search frameworks…"
        filters={[
          {
            key: 'status',
            label: 'Status',
            value: statusFilter,
            onChange: setStatusFilter,
            options: ADOPTION_STATUSES.map(s => ({ label: s, value: s })),
