                                <AlertDialogFooter>
                                  <AlertDialogCancel style={{ borderRadius: 0 }}>Cancel</AlertDialogCancel>
                                  <AlertDialogAction onClick={() => deleteIncident(inc.id)} style={{ borderRadius: 0, background: 'hsl(var(--destructive))' }}>
