            className="pl-8 h-8 text-sm"
            style={{ borderRadius: 0 }}
          />
        </div>
        <Select value={filterStatus} onValueChange={setFilterStatus}>
          <SelectTrigger className="w-44 h-8 text-xs" style={{ borderRadius: 0 }}>
            <Funnel size={12} className="mr-1" />
