import {
  Eye, PencilSimple, Trash, Plus, Buildings, Funnel,
  Warning, CheckCircle, ShieldWarning, Export, Handshake, Globe,
  CloudArrowUp, Siren, ChartPie, ClipboardText,
} from '@phosphor-icons/react';
